#include <stdio.h>
#include <stdlib.h>

// struct definition -- groups a name string and price float into one data type
typedef struct {
    char* name;    // pointer to the item's name string
    double price;  // the item's price as a 64-bit float
} Item;

// function returning Item pointer -- allocates heap memory for one Item and sets its fields
// caller is responsible for freeing the returned pointer
Item* create_item(const char* name, double price) {
    Item* item = malloc(sizeof(Item));  // allocates sizeof(Item) bytes on the heap
    item->name = (char*)name;           // WARNING: stores pointer directly, doesn't copy the string
    item->price = price;
    return item;  // returns heap-allocated Item -- must be freed by caller
}

// function returning double -- sums the price field of each Item in the array
// used by main() to get the total cost of all items
double total_price(Item** items, int count) {
    double total = 0;
    for (int i = 0; i < count; i++) {
        total += items[i]->price;  // arrow operator dereferences pointer to access price field
    }
    return total;
}

// entry point -- creates 3 items, prints their total, but never frees the allocated memory
int main() {
    Item* items[3];  // array of 3 pointers to Item structs (stack-allocated array of heap pointers)
    items[0] = create_item("Widget", 12.99);
    items[1] = create_item("Gadget", 5.50);
    items[2] = create_item("Doohickey", 3.75);

    // %.2f formats the double to 2 decimal places
    printf("Total: $%.2f\n", total_price(items, 3));

    // BUG: memory leak -- 3 malloc'd Items are never free()'d before program exits
    return 0;
}

