// function returning float -- sums a list of prices and applies a tax multiplier
// called by main() to compute the final cost
function calculate_total(list float prices, float tax_rate) returns float
    // guard clause -- returns 0 if the list is empty, avoids iterating over nothing
    if size(prices) == 0
        return 0.0
    end if

    // accumulator -- holds running sum, initialized to 0.0 (float)
    float subtotal = 0.0
    // for-each loop -- iterates every element in the prices list, adds to subtotal
    for each p in prices
        subtotal += p
    end for

    // multiplies subtotal by (1 + tax_rate) and returns the taxed total
    return subtotal * (1.0 + tax_rate)
end function

// entry point -- sets up test data and prints the result
// returns int (0 = success) as required by UL convention
function main() returns int
    // list literal -- 5 float prices
    list float items = [12.99, 5.50, 3.75, 8.00, 15.25]
    // calls calculate_total with 10% tax rate
    float total = calculate_total(items, 0.10)
    // change() casts float to string for concatenation -- UL has no string interpolation
    print "Total with tax: " + change(total)->string
    return 0
end function
